mapper.select:
SELECT COUNT(*)
FROM packing_item
WHERE trip_id = #{tripId} AND is_packed = #{isPacked}

SELECT pi.id, pi.trip_id, pi.name, pi.quantity, pi.category, pi.sub_category, 
       pi.notes, pi.is_packed, pi.source, pi.created_time, pi.updated_time,
       t.id as trip_id
FROM packing_item pi
         LEFT JOIN trip t ON pi.trip_id = t.id
WHERE pi.trip_id = #{tripId} 
  AND pi.name = #{name} 
  AND pi.source = #{source}
